import {THREE,cube,cylinder,sign} from './world.js?v=12';
import {makeCharacter} from './characters.js?v=12';
import {createTransit,updateTransit,boardBus,chooseSeat,moveInCabin,requestDeparture,requestStop,disembarkBus,cabinToWorld,busDoorWorld,serializeTransit,restoreTransit} from './transit.js?v=12';
export function boardingApproach(bus){const c=Math.cos(bus.yaw),s=Math.sin(bus.yaw);return {x:bus.x+2.05*c+2.7*s,z:bus.z-2.05*s+2.7*c,label:bus.name+' open door'};}
export function stopStatus(bus){return bus.obstructed?'Waiting: '+(bus.blockedReason||'road obstructed'):bus.status==='moving'?'Bus is on its route':'Doors open · departs in '+Math.ceil(bus.dwellRemaining)+'s';}
const KEY='sidequest-transit-v1';
export class TransitClient{
 constructor({world,hooks={}}){this.world=world;this.hooks=hooks;this.state=createTransit();this.models=new Map();this.clock=0;this.yieldTimes=new WeakMap();this.lastPosition=null;this.walkTarget=null;this.panelsig='';this.previous=new Map();this.colliderIds=new Set();this.root=new THREE.Group();world.scene.add(this.root);for(const b of this.state.buses)this.build(b);this.panel=document.createElement('section');this.panel.id='transitPanel';this.panel.style.cssText='position:fixed;right:18px;top:110px;max-width:310px;padding:14px;background:#102c2def;color:#fff6de;border:1px solid #b7c39a;border-radius:12px;z-index:45;font:14px system-ui;display:none';document.body.append(this.panel);this.panel.addEventListener('click',e=>{const id=e.target.closest('button')?.dataset.action;if(!id)return;const b=this.bus;if(id.startsWith('approach:')){const bus=this.state.buses.find(b=>b.id===id.slice(9));if(bus?.status==='stopped'){requestStop(this.state,bus.id);this.hooks.walk?.(boardingApproach(bus));}else this.hooks.toast?.('The bus is moving. Wait at the stop.');return;}if(id==='front'){chooseSeat(this.state,null);this.walkTarget=2.7;}else if(id==='back'){chooseSeat(this.state,null);this.walkTarget=-2.6;}else if(id==='stand')this.result(chooseSeat(this.state,null));else if(id==='stop')this.result(requestStop(this.state,b.id));else if(id==='go')this.result(requestDeparture(this.state,b.id));else if(id==='exit'){const r=disembarkBus(this.state,{blocked:p=>this.blocked(p,.4)});if(r.ok)this.hooks.onExit?.(r.position);this.result(r);}else if(id==='talk'){const p=b.passengers[Math.floor(this.clock)%b.passengers.length];this.hooks.toast?.(`${p.name}: ${p.line}`);}else if(id.startsWith('seat:'))this.result(chooseSeat(this.state,id.slice(5)));this.save();this.renderPanel();});this.sync(0);}
 get aboard(){return !!this.state.player.busId;}get bus(){return this.state.buses.find(b=>b.id===this.state.player.busId);}
 result(r){if(!r.ok)this.hooks.toast?.(r.reason);else this.hooks.onChange?.();return r;}
 build(b){const g=new THREE.Group();this.root.add(g);const shells=[];const body=b.id.endsWith('1')?'#326e63':'#a0643f';cube(2.45,.25,8.5,'#2c3435',0,.57,0,g);cube(2.15,.08,8.1,'#88897b',0,.75,0,g);
 for(const x of [-1.18,1.18]){for(const z of [-3,-1,1])cube(.12,.9,1.95,body,x,1.18,z,g);if(x<0)cube(.12,.9,1.95,body,x,1.18,3,g);for(const z of [-4,-2,0,2,4])cube(.09,1.5,.09,'#d3d7ce',x,2.05,z,g);}
 const roof=cube(2.5,.14,8.6,'#e5d7b5',0,2.85,0,g);shells.push(roof);
 const glass=new THREE.MeshStandardMaterial({color:'#96c6cc',transparent:true,opacity:.18,roughness:.2,depthWrite:false});for(const z of [-4.18,4.18])shells.push(cube(2.2,1.1,.06,glass,0,2.1,z,g));
 cube(2.3,.65,.1,body,0,1.1,-4.2,g);cube(2.3,.65,.1,body,0,1.1,4.2,g);
 const door=cube(.08,1.8,1.4,'#e4d9b7',1.2,1.65,2.8,g);cube(.65,.2,1.4,'#505651',1.28,.35,2.8,g);
 const wheels=[];for(const x of [-1.26,1.26])for(const z of [-2.7,2.7]){const w=cylinder(.48,.48,.25,'#242729',x,.48,z,g,18);w.rotation.z=Math.PI/2;wheels.push(w);}
 for(const seat of b.seats){cube(.65,.12,.65,'#4a797a',seat.x,1.15,seat.z,g);cube(.65,.65,.1,'#4a797a',seat.x,1.5,seat.z-.3,g);cylinder(.035,.035,.36,'#bbb9a4',seat.x,.95,seat.z,g);}
 for(const z of [-2,0,2]){cylinder(.025,.025,1.9,'#d8bd64',-.35,1.75,z,g);const rail=cylinder(.025,.025,6,'#d8bd64',-.35,2.65,0,g);rail.rotation.x=Math.PI/2;}
 const label=sign(b.name.toUpperCase(),2,.28);label.position.set(0,2.66,4.24);g.add(label);
 const occupants=[];for(const p of [...b.passengers,{id:'driver',seatId:null}]){try{const c=makeCharacter({color:p.id==='driver'?'#c3a16b':'#506b89',variant:'male'});const seat=b.seats.find(s=>s.id===p.seatId)||{x:-.65,z:3.4};c.position.set(seat.x,.42,seat.z);const bones=c.userData.bones||{};for(const key of ['LeftUpLeg','RightUpLeg'])if(bones[key])bones[key].rotation.x=-1.4;for(const key of ['LeftLeg','RightLeg'])if(bones[key])bones[key].rotation.x=1.3;g.add(c);occupants.push(c);}catch{/* Character loading is owned by main; vehicle still usable. */}}
 this.models.set(b.id,{g,door,wheels,shells,occupants});const collider={x:b.x,z:b.z,w:2.5,d:8.5,h:2.9,transitBusId:b.id};this.world.obstacles.push(collider);this.colliderIds.add(collider);this.previous.set(b.id,{x:b.x,z:b.z});}
 blocked(p,r=.4){return this.world.obstacles.some(o=>!o.transitBusId&&!(o.base>=3)&&Math.abs(p.x-o.x)<o.w/2+r&&Math.abs(p.z-o.z)<o.d/2+r);}
 vehicleBlocked(p,b){const c=Math.abs(Math.cos(b.yaw)),s=Math.abs(Math.sin(b.yaw)),rx=1.25*c+4.25*s,rz=1.25*s+4.25*c;if(this.world.obstacles.some(o=>!o.transitBusId&&!(o.base>=3)&&Math.abs(p.x-o.x)<o.w/2+rx&&Math.abs(p.z-o.z)<o.d/2+rz)){b.blockedReason='obstacle ahead';return true;}
 const body=(this.hooks.bodies?.()||[]).find(body=>!body.aboard&&Math.abs(p.x-body.x)<rx+(body.radius||.4)+.4&&Math.abs(p.z-body.z)<rz+(body.radius||.4)+.4);
 if(!body){b.blockedReason=null;return false;}b.blockedReason=this.hooks.canYield?.(body)?'pedestrian stepping aside':'pedestrian ahead';
 if(this.hooks.canYield?.(body)&&this.clock-(this.yieldTimes.get(body)??-99)>2){const side=body.x>=p.x?1:-1;for(const sign of [side,-side]){const target={x:p.x+sign*(rx+(body.radius||.4)+1),z:body.z};if(!this.blocked(target,.5)){this.yieldTimes.set(body,this.clock);this.hooks.onYield?.(body,b,target);break;}}}
 return true;}

 actions(position){this.lastPosition={x:position.x,z:position.z};if(this.aboard)return [];return this.state.buses.filter(b=>b.status==='stopped'&&Math.hypot(position.x-busDoorWorld(b).x,position.z-busDoorWorld(b).z)<2.1).map(b=>({id:'board:'+b.id,label:'Board '+b.name+' · leaves in '+Math.ceil(b.dwellRemaining)+'s',run:()=>{const r=boardBus(this.state,b.id,position);if(r.ok)this.hooks.onBoard?.(r.position);this.result(r);this.save();this.renderPanel();return r;}}));}
 tick(dt,input={}){if(input.paused){this.panel.style.display='none';return;}dt=Math.min(.1,Math.max(0,dt));this.clock+=dt;if(this.aboard&&this.state.player.mode==='standing'){const x=input.x??((input.d?1:0)-(input.a?1:0)),z=input.z??((input.w?1:0)-(input.s?1:0));if(x||z)this.walkTarget=null;const walkZ=this.walkTarget===null?z:Math.sign(this.walkTarget-this.state.player.local.z);moveInCabin(this.state,x*dt*1.6,walkZ*dt*1.6);if(this.walkTarget!==null&&Math.abs(this.walkTarget-this.state.player.local.z)<.12)this.walkTarget=null;}
 updateTransit(this.state,dt,{blocked:(p,b)=>this.vehicleBlocked(p,b)});this.sync(dt);this.renderPanel();if(Math.floor(this.clock)%5===0&&!this.justSaved){this.save();this.justSaved=true;}else if(Math.floor(this.clock)%5!==0)this.justSaved=false;}
 sync(dt){for(const b of this.state.buses){const m=this.models.get(b.id),p=this.previous.get(b.id);const distance=Math.hypot(b.x-p.x,b.z-p.z);m.g.position.set(b.x,0,b.z);m.g.rotation.y=b.yaw;for(const w of m.wheels)w.rotation.x-=distance/.48;m.door.visible=!b.doorsOpen;for(const shell of m.shells)shell.visible=this.state.player.busId!==b.id;const c=[...this.colliderIds].find(c=>c.transitBusId===b.id);c.x=b.x;c.z=b.z;c.w=2.5*Math.abs(Math.cos(b.yaw))+8.5*Math.abs(Math.sin(b.yaw));c.d=2.5*Math.abs(Math.sin(b.yaw))+8.5*Math.abs(Math.cos(b.yaw));this.previous.set(b.id,{x:b.x,z:b.z});}}
 playerPose(){if(!this.aboard)return null;return {...cabinToWorld(this.bus,this.state.player.local),yaw:this.bus.yaw,seated:this.state.player.mode==='seated'};}
 cameraTarget(){const p=this.playerPose();if(!p)return null;return {position:{...cabinToWorld(this.bus,{x:0,z:Math.max(-3.5,this.state.player.local.z-1.8)}),y:2.3},lookAt:{x:p.x,y:p.y+1.2,z:p.z},height:1.8};}
 markers(){return this.state.buses.map(b=>({x:b.x,z:b.z,name:b.name,id:b.id}));}
 renderPanel(){if(!this.aboard){const position=this.hooks.position?.()||this.lastPosition;const near=position&&this.state.buses.find(b=>b.route.points.some(p=>p.stop&&Math.hypot(p.x-position.x,p.z-position.z)<9));if(!near){this.panel.style.display='none';this.panelsig='';return;}const waiting=near.status==='stopped'&&Math.hypot(near.x-position.x,near.z-position.z)<12;const sig='outside:'+near.id+':'+stopStatus(near)+':'+waiting;this.panel.style.display='block';if(sig!==this.panelsig){this.panelsig=sig;this.panel.innerHTML=`<strong>${near.name}</strong><p>${stopStatus(near)}</p><p>Wait beside the road. E boards at the open door.</p>${waiting?`<button data-action="approach:${near.id}">Walk to the open door</button>`:''}`;}return;}const b=this.bus,p=this.state.player,next=b.route.points[b.segment+b.direction]||b.route.points[b.stopIndex];const signature=[b.id,b.status,p.mode,p.seatId,b.obstructed,b.arrivalCount,Math.ceil(b.dwellRemaining),b.stopRequested].join('|');this.panel.style.display='block';if(signature===this.panelsig)return;this.panelsig=signature;this.panel.innerHTML=`<strong>${b.name}</strong><p>${b.obstructed?'Waiting for a clear road':b.status==='moving'?(b.direction<0?'Reversing slowly to ':'Travelling to ')+(next.name||'next stop'):'Stopped · '+b.route.points[b.stopIndex].name+' · departs in '+Math.ceil(b.dwellRemaining)+'s'}</p><p>WASD: walk the aisle · ${p.mode}</p><div style="display:flex;flex-wrap:wrap;gap:5px">${b.seats.map(s=>`<button data-action="seat:${s.id}" ${s.occupant&&s.occupant!=='player'?'disabled':''}>${s.occupant==='player'?'Your seat':'Seat '+s.id}</button>`).join('')}<button data-action="stand">Stand</button><button data-action="front">Walk to door</button><button data-action="back">Walk to back</button><button data-action="talk">Talk to passengers</button><button data-action="go" ${b.status==='moving'?'disabled':''}>Ask driver to go</button><button data-action="stop">${b.stopRequested?'Stop requested':'Request next stop'}</button><button data-action="exit" ${b.status==='moving'?'disabled':''}>Exit at door</button></div>`;}
 save(){const data=serializeTransit(this.state);try{localStorage.setItem(KEY,JSON.stringify(data));}catch{}return data;}
 load(raw){let source=raw;if(source===undefined)try{source=localStorage.getItem(KEY);}catch{}const s=restoreTransit(source);if(!s)return false;this.state=s;this.panelsig='';this.sync(0);this.renderPanel();return true;}
 reset(){this.state=createTransit();this.panelsig='';this.sync(0);this.save();this.renderPanel();}
 dispose(){this.panel.remove();this.root.removeFromParent();this.world.obstacles=this.world.obstacles.filter(o=>!this.colliderIds.has(o));}
}
